    const userGradesList = Array.isArray(user.assignedGrades) && user.assignedGrades.length > 0

      ? user.assignedGrades

      : ["1 de Secundaria", "2 de Secundaria", "3 de Secundaria", "4 de Secundaria", "5 de Secundaria"];



