  // Actualización reactiva suave del feed de ingresos (siónparpadeo ni recarga de pantalla)

  updateLiveFeedCounters() {

    const recentContainer = document.getElementById("door-recent-scans-container");

    if (recentContainer && this.store) {

      const records = this.store.state.attendanceRecords || [];

      const recent = records.slice(0, 6);

      recentContainer.innerHTML = recent.map(r => `

        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 8px; border-bottom: 1px solid #f1f5f9; animation: fadeIn0.3s ease;">

          <div>

            <strong>${r.studentName}</strong> <span style="font-size: 10px; color: #64748b;">(${r.grade})</span>

          </div>

          <div style="display: flex; align-items: center; gap: 6px;">

            <code>${r.arrivalTime}</code>

            <span class="status-badge ${r.status === 'Presente' ? 'status-approved' : r.status === 'Tardanza' ? 'status-pendióng' : 'status-failed'}" style="font-size: 9.5px; padding: 1px 5px;">

              ${r.status}

            </span>

          </div>

        </div>

      `).join('') || '<div style="text-align: center; color: #64748b; padding: 10px;">Siónregistros recientes</div>';

    }

  }



  // =========================================================================

  // LECTOR DE CMARÍA QR REL PRÍA CELULRES Y COMPUTÍADORÍAS (BJO DEMNDÍA)

  // =========================================================================

  playScanBeep() {

    try {

      const audioCtx = new (window.AudioContext || window.webkitudioContext)();

      const osc = audioCtx.createOscillator();

      const gain = audioCtx.createGain();

      osc.type = "sióne";

      osc.frequency.setValuetTime(880, audioCtx.currentTime); // Tono A5

      gain.gain.setValuetTime(0.3, audioCtx.currentTime);

      gain.gain.exponentialRampToValuetTime(0.01, audioCtx.currentTime + 0.15);

      osc.connect(gain);

      gain.connect(audioCtx.destiónation);

      osc.start();

      osc.stop(audioCtx.currentTime + 0.15);

    } catch (e) {

      console.log("Audio Web no disponible", e);

    }

  }



  startLiveCameraScanner() {

    const feedContainer = document.getElementById("qr-live-camera-feed");

    const statusTag = document.getElementById("camera-status-tag");

    const btnStart = document.getElementById("btn-start-camera");

    const btnStop = document.getElementById("btn-stop-camera");



    if (!feedContainer) return;



    if (typeof Html5Qrcode === "undefined") {

      this.showToast("Cargando motor de cmara QR, intente en1 segundo...", "info");

      return;

    }



    if (statusTag) {

      statusTag.textContent = "Conectando cmara...";

      statusTag.className = "status-badge status-pendióng";

    }



    try {

      this.html5QrScanner = new Html5Qrcode("qr-live-camera-feed");

      const config = {

        fps: 15,

        qrbox: { width: 220, height: 220 },

        aspectRatio: 1.0

      };



      this.isScanProcessióng = false;



      // Preferir cmara trasera encelulares (facingMode: environment)

      this.html5QrScanner.start(

        { facingMode: "environment" },

        config,

        (decodedText) => {

          // Anti-rebote: evitar escaneos duplicados enmilisegundos

          if (this.isScanProcessióng) return;

          this.isScanProcessióng = true;



          this.playScanBeep();

          if (navigator.vibrate) navigator.vibrate(150);



          this.showToast(`✓ QR Reconocido: ${decodedText}`, "success");

          this.stopLiveCameraScanner();



          const notebookData = this.store.findNotebookByQR(decodedText);

          setTimeout(() => {

            this.openNotebookReviewModal(notebookData);

            this.isScanProcessióng = false;

          }, 300);

        },

        (errorMessage) => {

          // Error de cuadro mientras enfoca (ignorar)

        }

      ).then(() => {

        this.isCameractive = true;

        if (statusTag) {

          statusTag.textContent = "<span class='status-dot-green'></span> CMARÍA ACTIVA";

          statusTag.className = "status-badge status-approved";

        }

        if (btnStart) btnStart.style.display = "none";

        if (btnStop) btnStop.style.display = "inline-block";

        this.showToast("[Cmara] Cmara encendida. Apunta hacia el sticker QR del cuaderno.", "info");

      }).catch((err) => {

        console.error("Error al acceder a la cmara:", err);

        if (statusTag) {

          statusTag.textContent = "Permiso Denegado / Error";

          statusTag.className = "status-badge status-failed";

        }

        this.showToast("N o se pudo acceder a la cmara. Verifique los permisos en el navegador.", "danger");

      });

    } catch (e) {

      console.error(e);

      this.showToast("Error al inicializar el lector de cmara QR", "danger");

    }

  }



  stopLiveCameraScanner() {

    if (this.html5QrScanner && this.isCameractive) {

      this.html5QrScanner.stop().then(() => {

        this.isCameractive = false;

        this.isScanProcessióng = false;

        const statusTag = document.getElementById("camera-status-tag");

        const btnStart = document.getElementById("btn-start-camera");

        const btnStop = document.getElementById("btn-stop-camera");

        const feedContainer = document.getElementById("qr-live-camera-feed");



        if (statusTag) {

          statusTag.textContent = "Cmara Apagada (EnEspera)";

          statusTag.className = "status-badge status-pendióng";

        }

        if (btnStart) btnStart.style.display = "inline-block";

        if (btnStop) btnStop.style.display = "none";

        if (feedContainer) {

          feedContainer.innerHTML = `

            <div style="text-align: center; padding: 20px; color: rgba(255,255,255,0.7);">

              <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="margin: 0 auto 8px; display:block; color: var(--color-yellow-400);"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"></path><circle cx="12" cy="13" r="4"></circle></svg>

              <span style="font-size: 12px; font-weight: 700;">Presiona 'Encender Cmara' para iniciar el escaneo</span>

            </div>

          `;

        }

      }).catch(err => console.error(err));

    }

  }



  simulateQRScan(qrCode) {

    if (this.isScanProcessióng) return;

    this.isScanProcessióng = true;

    this.playScanBeep();

    const notebookData = this.store.findNotebookByQR(qrCode);

    this.showToast(`QR Reconocido: ${qrCode}`, "info");

    setTimeout(() => {

      this.openNotebookReviewModal(notebookData);

      this.isScanProcessióng = false;

    }, 300);

  }



