                      <input type="checkbox" name="${prefix}-check" value="${cName}" ${chk ? 'checked' : ''} onchange="window.app.updateCoursesCounter('${prefix}')" data-area="${cat.category.toLowerCase()}" style="cursor: pointer;" />

