  filterIncidentsTable(query) {

    const q = (query || "").toLowerCase();

    const rows = document.querySelectorAll("#incidents-main-table tbody tr");

    rows.forEach(row => {

      const text = row.innerText.toLowerCase();

      row.style.display = text.includes(q) ? "" : "none";

    });

  }



