  clearScheduleGrade(gradeId) {

    const catalog = this.store.state.gradesCatalog || initialData.gradesCatalog;

    const currentGrade = catalog.find(g => g.id === gradeId) || catalog[4];



    if (confirm(`¿Está seguro de que desea limpiar todos los bloques lectivos del horario de ${currentGrade.label}? Los recesos se mantendrn.`)) {

      this.store.clearGradeSchedule(gradeId);

      this.showToast(`✓ Horario de ${currentGrade.label} reseteado a plantilla vaca`, "info");

      this.render();

    }

  }



